import React, { useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { Users } from 'lucide-react';
import type { KelasResponse } from '@/types';
import { apiService } from '@/services';
import { extractString, extractNumber, extractDate } from '@/utils';
import { getModeColor, formatDate } from '../utils';
import MeetingRecapGrid from './MeetingRecapGrid';

interface ClassCardProps {
  kelas: KelasResponse;
  courseCode: string;
  courseName: string;
}

const ClassCard: React.FC<ClassCardProps> = ({ kelas, courseCode, courseName }) => {
  const navigate = useNavigate();

  // Fetch meetings for this class
  const meetingsQuery = useQuery({
    queryKey: ['admin-class-meetings', kelas.id],
    queryFn: async () => {
      try {
        return await apiService.getMeetingsByClass(kelas.id);
      } catch (err) {
        return [];
      }
    },
  });

  // Fetch students for this class
  const studentsQuery = useQuery({
    queryKey: ['admin-class-students', kelas.id],
    queryFn: async () => {
      try {
        const students = await apiService.getClassStudents(kelas.id);
        return Array.isArray(students) ? students.length : 0;
      } catch (err) {
        return 0;
      }
    },
  });

  const meetings = useMemo(() => meetingsQuery.data ?? [], [meetingsQuery.data]);
  const totalStudents = useMemo(() => studentsQuery.data ?? 0, [studentsQuery.data]);

  return (
    <div className="p-2 bg-gray-50 rounded text-xs hover:bg-gray-100 transition-colors group">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-2">
          <h4 className="font-medium text-gray-900 whitespace-nowrap">Class {extractString(kelas.nama_kelas)}</h4>
          {extractString(kelas.mode_kuliah) && (
            <span className={`px-1.5 py-0.5 text-xs font-medium rounded whitespace-nowrap ${getModeColor(extractString(kelas.mode_kuliah))}`}>
              {extractString(kelas.mode_kuliah)}
            </span>
          )}
        </div>

        <div className="flex items-center gap-1.5 text-gray-600 flex-wrap">
          {extractDate(kelas.tgl_mulai) && <span className="whitespace-nowrap">{formatDate(extractDate(kelas.tgl_mulai))}</span>}
          {extractNumber(kelas.sks_tatap_muka) > 0 && <span className="whitespace-nowrap">{extractNumber(kelas.sks_tatap_muka)}SKS</span>}
          <button
            onClick={(e) => {
              e.stopPropagation();
              navigate(
                `/class-summary/${kelas.id}?courseCode=${encodeURIComponent(courseCode)}&courseName=${encodeURIComponent(courseName)}&className=${encodeURIComponent(extractString(kelas.nama_kelas))}&sksTatapMuka=${extractNumber(kelas.sks_tatap_muka)}&sksPraktek=${extractNumber(kelas.sks_praktek)}&sksPrakLapangan=${extractNumber(kelas.sks_prak_lapangan)}&sksSimulasi=${extractNumber(kelas.sks_simulasi)}&from=admin/class-management`
              );
            }}
            className="ml-2 px-2 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors flex items-center gap-1 whitespace-nowrap"
            title="View attendance matrix"
          >
            <Users className="h-3 w-3" />
            <span>Summary</span>
          </button>
        </div>
      </div>

      {extractString(kelas.bahasan) && (
        <p className="text-gray-600 mt-1">
          {extractString(kelas.bahasan)}
        </p>
      )}

      <div className="mt-2">
        <div className="flex items-center justify-between text-[11px] text-gray-600 mb-1">
          <span className="font-semibold text-gray-800">Meeting Recap</span>
          <span className="whitespace-nowrap">
            {meetings.length ? `${meetings.length} meeting${meetings.length !== 1 ? 's' : ''}` : 'No meetings'}
          </span>
        </div>

        <MeetingRecapGrid meetings={meetings} totalStudents={totalStudents} />
      </div>
    </div>
  );
};

export default ClassCard;
