import React, { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { CheckCircle, XCircle, User, Loader2 } from 'lucide-react';
import { apiService } from '@/services';
import { extractString, extractDate } from '@/utils';
import { parseAbsensiAktif } from '../utils';

export type MeetingRecapItem = {
  id: number;
  weekNumber: number;
  date: Date | null;
  topic?: string;
  studentAttendanceComplete: boolean;
  lecturerAssigned: boolean;
  totalStudents: number;
  recordedAttendances: number;
  absensiAktif: boolean;
};

interface MeetingRecapGridProps {
  meetings: Array<{ id: number; pertemuan_ke: number; tgl_pertemuan?: any; topik?: any; idDosen?: any; id_dosen?: any; absensi_aktif?: any }>;
  totalStudents: number;
}

const MeetingRecapGrid: React.FC<MeetingRecapGridProps> = ({ meetings, totalStudents }) => {
  const meetingIds = useMemo(() => meetings.map(m => m.id), [meetings]);

  // Use the new efficient batch endpoint
  const attendanceQuery = useQuery({
    queryKey: ['admin-meeting-attendances-batch', meetingIds],
    queryFn: async () => {
      if (meetingIds.length === 0) return {};
      
      try {
        const batchData = await apiService.getMeetingsBatch({
          meeting_ids: meetingIds,
          include_attendance_count: true,
        });
        
        const result: Record<number, number> = {};
        batchData.forEach(meeting => {
          result[meeting.id] = meeting.total_attendances ?? 0;
        });
        return result;
      } catch (err) {
        return {};
      }
    },
    enabled: meetingIds.length > 0,
  });

  const meetingRecap = useMemo(() => {
    return meetings
      .map(meeting => {
        const recordedAttendances = attendanceQuery.data?.[meeting.id] ?? 0;
        const studentAttendanceComplete = totalStudents > 0 && recordedAttendances >= totalStudents;
        const lecturerId = extractString((meeting as any).idDosen ?? meeting.id_dosen);
        const lecturerAssigned = Boolean(lecturerId);

        return {
          id: meeting.id,
          weekNumber: meeting.pertemuan_ke,
          date: extractDate(meeting.tgl_pertemuan as any),
          topic: extractString(meeting.topik, ''),
          studentAttendanceComplete,
          lecturerAssigned,
          totalStudents,
          recordedAttendances,
          absensiAktif: parseAbsensiAktif((meeting as any).absensi_aktif),
        } satisfies MeetingRecapItem;
      })
      .sort((a, b) => a.weekNumber - b.weekNumber);
  }, [meetings, attendanceQuery.data, totalStudents]);

  if (attendanceQuery.isFetching) {
    return (
      <div className="flex items-center gap-2 text-gray-500">
        <Loader2 className="h-4 w-4 animate-spin" />
        <span>Loading meeting recap...</span>
      </div>
    );
  }

  if (meetingRecap.length === 0) {
    return <div className="text-gray-500 text-[11px]">No meetings scheduled</div>;
  }

  return (
    <div className="flex gap-1 flex-wrap">
      {meetingRecap.map(meeting => {
        const dateStr = meeting.date
          ? meeting.date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
          : '-';

        return (
          <div
            key={meeting.id}
            className="flex flex-col items-center gap-1 p-2 rounded border border-gray-200 bg-white shadow-sm min-w-[80px]"
            title={`Week ${meeting.weekNumber} - ${dateStr}${meeting.topic ? ` - ${meeting.topic}` : ''}\nStudent Attendance: ${meeting.recordedAttendances}/${meeting.totalStudents}\nLecturer Assigned: ${meeting.lecturerAssigned ? 'Yes' : 'No'}\nAttendance: ${meeting.absensiAktif ? 'Active' : 'Inactive'}`}
          >
            <div className="text-[11px] font-semibold text-gray-700">W{meeting.weekNumber}</div>
            <div className="flex gap-1 items-center justify-center h-5">
              {meeting.studentAttendanceComplete ? (
                <CheckCircle className="h-4 w-4 text-green-600" />
              ) : meeting.recordedAttendances > 0 ? (
                <CheckCircle className="h-4 w-4 text-orange-500" />
              ) : (
                <XCircle className="h-4 w-4 text-gray-300" />
              )}

              {meeting.lecturerAssigned ? (
                <User className="h-4 w-4 text-blue-600" />
              ) : (
                <User className="h-4 w-4 text-gray-300" />
              )}
            </div>
            <div className="text-[11px] text-gray-500 text-center leading-tight">{dateStr}</div>
            <div className="flex items-center justify-center">
              <div className={`h-2 w-2 rounded-full ${meeting.absensiAktif ? 'bg-green-600' : 'bg-gray-400'}`} />
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default MeetingRecapGrid;
