import React, { useEffect, useMemo, useState } from 'react';
import {
  Calendar,
  BookOpen,
  Search,
  Filter,
  AlertCircle,
} from 'lucide-react';
import type { CourseWithClasses } from '@/types';
import { useAuth, useTranslation } from '@/contexts';
import { useCourses, usePrograms } from '@/hooks';
import { getSemesterLabel } from '../utils';
import CourseCard from './CourseCard';

interface FilterState {
  searchQuery: string;
  filterProgram: string;
  filterYear: string;
  filterTerm: '1' | '2';
}

const ClassManagement: React.FC = () => {
  const { currentSemester } = useAuth();
  const { t } = useTranslation();
  const [courses, setCourses] = useState<CourseWithClasses[]>([]);
  const [programs, setPrograms] = useState<Array<{ kode_prodi: string; nama_prodi: string }>>([]);
  const [error, setError] = useState<string | null>(null);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [filters, setFilters] = useState<FilterState>({
    searchQuery: '',
    filterProgram: 'all',
    filterYear: '',
    filterTerm: '1',
  });

  // Compute filterSemester from year and term
  const filterSemester = useMemo(() => {
    return filters.filterYear ? `${filters.filterYear}${filters.filterTerm}` : '';
  }, [filters.filterYear, filters.filterTerm]);

  // React Query: programs and courses (cached)
  const { data: programsData } = usePrograms();
  const { data: coursesData, error: coursesError } = useCourses(
    useMemo(
      () =>
        filterSemester
          ? { semester: filterSemester, include_classes: true }
          : undefined,
      [filterSemester]
    )
  );

  // Sync hook data into local state
  useEffect(() => {
    if (programsData) {
      setPrograms(programsData);
    }
  }, [programsData]);

  useEffect(() => {
    if (coursesError) {
      const msg = coursesError instanceof Error ? coursesError.message : 'Failed to load courses';
      setError(msg);
      setCourses([]);
    } else {
      setError(null);
    }
  }, [coursesError]);

  useEffect(() => {
    if (Array.isArray(coursesData)) {
      setCourses(coursesData);
    }
  }, [coursesData]);

  // Sync filterYear and filterTerm with currentSemester when it changes
  useEffect(() => {
    if (currentSemester && !filters.filterYear) {
      const year = currentSemester.slice(0, 4);
      const term = currentSemester.slice(4) as '1' | '2';
      setFilters((prev) => ({ ...prev, filterYear: year, filterTerm: term }));
    }
  }, [currentSemester, filters.filterYear]);

  // Filter courses based on search and program filters
  const filteredCourses = useMemo(() => {
    let filtered = courses;

    // Search filter
    if (filters.searchQuery) {
      filtered = filtered.filter(
        (course) =>
          course.nama_mk.toLowerCase().includes(filters.searchQuery.toLowerCase()) ||
          course.kode_mk.toLowerCase().includes(filters.searchQuery.toLowerCase())
      );
    }

    // Program filter
    if (filters.filterProgram !== 'all') {
      filtered = filtered.filter((course) => course.kode_prodi === filters.filterProgram);
    }

    return filtered;
  }, [courses, filters.searchQuery, filters.filterProgram]);

  const totalCourses = filteredCourses.length;
  const totalClasses = filteredCourses.reduce((sum, course) => sum + (course.classes?.length || 0), 0);

  const handleFilterChange = (key: keyof FilterState, value: string) => {
    setFilters((prev) => ({ ...prev, [key]: value }));
  };

  const toggleCourseExpand = (kode_mk: string) => {
    const newExpanded = new Set(expandedCourses);
    if (newExpanded.has(kode_mk)) {
      newExpanded.delete(kode_mk);
    } else {
      newExpanded.add(kode_mk);
    }
    setExpandedCourses(newExpanded);
  };

  return (
    <div className="max-w-7xl mx-auto">
      {/* Header */}
      <div className="mb-6">
        <div className="flex items-center justify-between mb-2">
          <h1 className="text-2xl font-bold text-gray-900">Class Management</h1>
          <div className="flex items-center gap-2 text-sm">
            <Calendar className="h-4 w-4 text-gray-500" />
            <span className="text-gray-500">Current Semester:</span>
            <span className="font-medium text-gray-900">{getSemesterLabel(currentSemester)}</span>
          </div>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
          <div className="card bg-gradient-to-br from-blue-50 to-blue-100 border-blue-200">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-blue-600 rounded-lg">
                <BookOpen className="h-5 w-5 text-white" />
              </div>
              <div>
                <p className="text-sm text-blue-600 font-medium">Total Courses</p>
                <p className="text-2xl font-bold text-blue-900">{totalCourses}</p>
              </div>
            </div>
          </div>

          <div className="card bg-gradient-to-br from-green-50 to-green-100 border-green-200">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-green-600 rounded-lg">
                <BookOpen className="h-5 w-5 text-white" />
              </div>
              <div>
                <p className="text-sm text-green-600 font-medium">{t('adminClasses.totalClasses')}</p>
                <p className="text-2xl font-bold text-green-900">{totalClasses}</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Filters & Search */}
      <div className="card mb-6">
        <div className="flex flex-col sm:flex-row gap-3">
          {/* Search */}
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-gray-400" />
            <input
              type="text"
              placeholder={t('adminClasses.searchPlaceholder')}
              value={filters.searchQuery}
              onChange={(e) => handleFilterChange('searchQuery', e.target.value)}
              className="input-field pl-10 w-full"
            />
          </div>

          {/* Academic Year Filter */}
          <div className="flex items-center gap-2 flex-shrink-0">
            <Calendar className="h-5 w-5 text-gray-400 flex-shrink-0" />
            <div className="flex items-center gap-1">
              <input
                type="number"
                value={filters.filterYear}
                onChange={(e) => handleFilterChange('filterYear', e.target.value)}
                placeholder={t('adminClasses.year')}
                className="input-field w-[80px] text-center"
                min={new Date().getFullYear() - 10}
                max={new Date().getFullYear() + 5}
              />
              <span className="text-gray-500 font-medium">/</span>
              <input
                type="number"
                value={filters.filterYear ? parseInt(filters.filterYear) + 1 : ''}
                disabled
                className="input-field w-[80px] text-center bg-gray-50 text-gray-600"
                readOnly
              />
            </div>
          </div>

          {/* Semester Type Filter */}
          <div className="flex items-center gap-2 flex-shrink-0">
            <select
              value={filters.filterTerm}
              onChange={(e) => handleFilterChange('filterTerm', e.target.value)}
              className="input-field min-w-[120px]"
            >
              <option value="1">{t('adminClasses.ganjil')}</option>
              <option value="2">{t('adminClasses.genap')}</option>
            </select>
          </div>

          {/* Program Filter */}
          <div className="flex items-center gap-2 flex-shrink-0">
            <Filter className="h-5 w-5 text-gray-400 flex-shrink-0" />
            <select
              value={filters.filterProgram}
              onChange={(e) => handleFilterChange('filterProgram', e.target.value)}
              className="input-field min-w-[200px]"
            >
              <option value="all">{t('adminClasses.allPrograms')}</option>
              {programs.map((prodi) => (
                <option key={prodi.kode_prodi} value={prodi.kode_prodi}>
                  {prodi.nama_prodi} ({prodi.kode_prodi})
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Error State */}
      {error && (
        <div className="card bg-red-50 border-red-200 mb-6">
          <div className="flex items-center gap-3 text-red-700">
            <AlertCircle className="h-5 w-5 flex-shrink-0" />
            <div>
              <p className="font-medium">{t('adminClasses.errorLoading')}</p>
              <p className="text-sm text-red-600">{error}</p>
            </div>
          </div>
        </div>
      )}

      {/* Courses List */}
      {filteredCourses.length === 0 ? (
        <div className="card text-center py-12">
          <BookOpen className="h-12 w-12 text-gray-300 mx-auto mb-3" />
          <p className="text-gray-500 mb-2">{t('adminClasses.noCourses')}</p>
          <p className="text-sm text-gray-400">
            {filters.searchQuery || filters.filterProgram !== 'all'
              ? t('adminClasses.tryAdjusting')
              : t('adminClasses.noCoursesAvailable')}
          </p>
        </div>
      ) : (
        <div className="space-y-2">
          {filteredCourses.map((course) => (
            <CourseCard
              key={course.kode_mk}
              course={course}
              isExpanded={expandedCourses.has(course.kode_mk)}
              onToggleExpand={() => toggleCourseExpand(course.kode_mk)}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default ClassManagement;
